### 3. Migration to Secrets Manager

For production environments, use a proper secrets manager instead of environment files:

```javascript
// services/secrets.js
class SecretsManager {
  constructor() {
    this.secretsCache = new Map();
    this.ttl = 1000 * 60 * 60; // 1 hour cache
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.secretsCache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.ttl) {
      return cached.value;
    }

    let secretValue;

    // Try different providers in order of preference
    try {
      // 1. Try AWS Secrets Manager
      secretValue = await this._getFromAWSSecrets(secretName);
    } catch (awsError) {
      try {
        // 2. Try environment variables (fallback)
        secretValue = process.env[secretName];
        if (!secretValue) {
          throw new Error(`Secret ${secretName} not found in environment`);
        }
      } catch (envError) {
        throw new Error(`Failed to retrieve secret ${secretName}: ${awsError.message}`);
      }
    }

    // Cache the secret
    this.secretsCache.set(secretName, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  }

  async _getFromAWSSecrets(secretName) {
    // This is a simplified example - in practice, use AWS SDK
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager();

    const data = await client.getSecretValue({ SecretId: secretName }).promise();
    return data.SecretString;
  }

  // Clear cache (useful for testing or forced rotation)
  clearCache() {
    this.secretsCache.clear();
  }
}

module.exports = new SecretsManager();
```

